import { Module, MutationTree } from 'vuex';
import { RootState } from '@/store';

export interface User {
  id?: number;
  name: string;
  email: string;
  last_name: string;
  spiritual_name: string;
  subscribe_level: string;
}

export interface UserState {
  data: object | User;
}

const state: UserState = {
  data: {}
};

const mutations: MutationTree<UserState> = {
  set(state, user) {
    state.data = user;
  },
  unset(state) {
    state.data = {};
  }
};

export const module = {
  namespaced: true,
  state,
  mutations
} as Module<UserState, RootState>;
