import { endpoints } from '@/api-endpoints.json';
import { ApiService } from '@/services/Api/ApiService';
import { store } from '@/store';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';

export type SearchBaseOptions = {
  book_slug: string;
  search_in_poem: boolean;
  exact: boolean;
  consider_diacritics: boolean;
  equalize_writing: boolean;
  books: Array<number>;
  book_sections: Array<string>;
  categories: Array<number>;
};

export interface SearchOptions extends SearchBaseOptions {
  size: number;
  from: number;
}

export interface SearchItem {
  book_slug: string;
  section_slug: string;
  title: string;
  body: string;
  highlight: Array<string>;
  paths: Array<Array<{ title: string }>>;
}

export default class SearchService {
  static async search(
    language: string = LANGUAGE_CODE_DEFAULT,
    query: string,
    options: Partial<SearchOptions> = {}
  ) {
    return new ApiService()
      .setEndpoint(endpoints.search.query.replace(':lang', language))
      .setToken(store.state.auth.token)
      .setBody({
        language,
        query,
        ...options
      })
      .post()
      .then(response => response.data);
  }

  static async getSuggestions(
    language: string = LANGUAGE_CODE_DEFAULT,
    query: string,
    options: Partial<SearchBaseOptions> = {}
  ) {
    return new ApiService()
      .setEndpoint(endpoints.search.autocomplete.replace(':lang', language))
      .setToken(store.state.auth.token)
      .setBody({
        language,
        query,
        ...options
      })
      .post()
      .then(response => response.data);
  }

  static async getSearchHistory() {
    const endpoint = endpoints.search.history;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .get()
      .then(response => response.data.data);
  }

  static async clearSearchHistory() {
    const endpoint = endpoints.search.history;
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .delete()
      .then(response => response.data.data);
  }

  static async getPriorityResults(language: string = LANGUAGE_CODE_DEFAULT, query: string) {
    const endpoint = endpoints.search.priority.replace(':lang', language);
    return new ApiService()
      .setEndpoint(endpoint)
      .setToken(store.state.auth.token)
      .setBody({
        query
      })
      .post()
      .then(response => response.data.data);
  }
}
