































import Component from 'vue-class-component';
import Vue from 'vue';
import CrossBolderIcon from '@/assets/icons/cross-bolder.svg';
import { Prop, Watch } from 'vue-property-decorator';
import { getTranslation } from '@/services/Translation';

let overlayIndex = 0;

@Component({
  components: {
    CrossBolderIcon
  }
})
export default class Overlay extends Vue {
  titleId = `overlay-title-${++overlayIndex}`;

  previouslyFocused?: HTMLElement;

  getTranslation = getTranslation;

  @Prop({ required: false })
  centered?: boolean;

  @Prop({ required: true })
  title!: string;

  @Prop({ required: false })
  visible?: boolean;

  mounted() {
    if (this.visible) {
      this.focusDialog();
    }
  }

  beforeDestroy() {
    this.restoreFocus();
  }

  @Watch('visible')
  onVisibleChange(visible: boolean) {
    if (visible) {
      this.focusDialog();
    } else {
      this.restoreFocus();
    }
  }

  focusDialog() {
    this.previouslyFocused = document.activeElement as HTMLElement;
    this.$nextTick(() => {
      const dialog = this.$refs.dialog as HTMLElement;
      if (dialog) {
        dialog.focus();
      }
    });
  }

  restoreFocus() {
    if (this.previouslyFocused && document.body.contains(this.previouslyFocused)) {
      this.previouslyFocused.focus();
    }
    this.previouslyFocused = undefined;
  }

  onKeydown(event: KeyboardEvent) {
    if (event.key === 'Escape') {
      event.preventDefault();
      this.$emit('close');
      return;
    }
    if (event.key !== 'Tab') {
      return;
    }
    const dialog = this.$refs.dialog as HTMLElement;
    const focusable = dialog
      ? (Array.from(
          dialog.querySelectorAll(
            'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
          )
        ) as HTMLElement[]).filter(
          element =>
            element.tabIndex >= 0 &&
            element.getAttribute('aria-hidden') !== 'true' &&
            element.offsetParent !== null
        )
      : [];
    if (!focusable.length) {
      event.preventDefault();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }
}
