

























import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Ref } from 'vue-property-decorator';
import { PagingItem } from '@/services/Navigation/types';
import UrlBuilderService from '@/services/UrlBuilderService';

@Component
export default class BottomBarControlValue extends Vue {
  listIsVisible: boolean = false;

  @Prop({ required: true })
  number!: number;

  @Prop({ required: false })
  list!: Array<number>;

  @Ref('button')
  refButton?: HTMLButtonElement;

  @Ref('list')
  refList?: HTMLDivElement;

  mounted() {
    document.addEventListener('click', this.handleClickOutside, false);
  }

  updated() {
    if (!this.refList) {
      return;
    }
    const current = this.refList.querySelector('.current') as HTMLDivElement;
    if (this.listIsVisible && current) {
      this.refList.scrollTo({ top: current.offsetTop });
    }
  }

  handleClickOutside(e: MouseEvent) {
    if (!this.refButton) {
      return;
    }
    if (this.listIsVisible && !this.refButton.contains(e.target as Node)) {
      this.listIsVisible = false;
    }
  }

  getItemUrl(item: PagingItem) {
    return UrlBuilderService.getBookSectionUrl({
      language: this.$route.params.language,
      categorySlug: this.$route.params.category,
      bookSlug: this.$route.params.book,
      bookSectionSlug: item.bookSectionSlug
    });
  }
}
