














































import Vue from 'vue';
import AuthLayout from '@/layouts/AuthLayout.vue';
import AuthService from '@/services/Api/AuthService';
import Component from 'vue-class-component';
import { getTranslation } from '@/services/Translation';
import InputText from '@/components/ui/InputText.vue';

@Component({
  components: { InputText, AuthLayout }
})
export default class ResetPassword extends Vue {
  loading = false;
  token = '';
  email = '';
  password = '';
  passwordConfirmation = '';
  error = '';
  errorsByField = null;

  getTranslation = getTranslation;

  created() {
    this.token = this.$route.params.token;
    this.email = typeof this.$route.query.email === 'string' ? this.$route.query.email : '';
  }

  async submit() {
    if (this.loading) {
      return;
    }
    this.loading = true;
    try {
      await AuthService.resetPassword(this.token, this.email, this.password, this.passwordConfirmation);
      this.loading = false;
      this.$router.push('/').catch(() => {});
    } catch (e) {
      this.loading = false;
      this.errorsByField = e.response && e.response.data && e.response.data.errors;
      this.error =
        e.response && e.response.data && e.response.data.message
          ? e.response.data.message
          : e.message || getTranslation('defaultErrorMessage');
    }
  }
}
