





















































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import InputText from '@/components/ui/InputText.vue';
import ZoomIcon from '@/assets/icons/zoom.svg';
import IconCross from '@/assets/icons/cross.svg';
import SearchService, { SearchBaseOptions } from '@/services/Api/SearchService';
import Loader from '@/components/ui/Loader.vue';
import { Getter } from 'vuex-class';
import { getTranslation } from '@/services/Translation';
import SearchScopeService from '@/services/SearchScopeService';

@Component({
  components: { Loader, InputText, ZoomIcon, IconCross }
})
export default class SearchInput extends Vue {
  query: string;

  suggestionTimeout?: number;

  suggestions: Array<{ title: string; url: string }> = [];

  loadingSuggestions: boolean = false;

  suggestionsRequestId: number = 0;

  getTranslation = getTranslation;

  @Prop({ required: false, default: '' })
  placeholder!: string;

  @Prop({ required: false })
  value?: string;

  @Prop({ required: false })
  hasSuggestions?: boolean;

  @Getter('searchOptions', { namespace: 'search' })
  searchOptions!: SearchBaseOptions;

  constructor() {
    super();
    this.query = this.value || '';
  }

  @Watch('value')
  onValueChange() {
    this.query = this.value || '';
  }

  handleInputChange(value: string) {
    this.query = value;
    this.$emit('change', value);
    this.actualizeSuggestions();
  }

  handlePressEnter() {
    this.$emit('submit', this.query);
    this.resetSuggestions();
  }

  handleClear() {
    this.query = '';
    this.$emit('clear');
    this.resetSuggestions();
  }

  handleInputFocus() {
    this.actualizeSuggestions();
  }

  handleInputBlur() {
    setTimeout(() => {
      this.resetSuggestions();
    }, 200);
  }

  handleSuggestionClick(suggestion: string) {
    this.$emit('submit', suggestion);
    this.resetSuggestions();
  }

  actualizeSuggestions() {
    if (!this.hasSuggestions) {
      return;
    }
    if (this.suggestionTimeout) {
      clearTimeout(this.suggestionTimeout);
    }
    this.suggestionTimeout = setTimeout(async () => {
      const suggestions = await this.fetchSuggestions();
      if (suggestions) {
        this.suggestions = suggestions;
      }
    }, 400);
  }

  async fetchSuggestions() {
    if (!(this.query && this.query.length > 2)) {
      return [];
    }
    if (SearchScopeService.hasActiveScope(this.searchOptions)) {
      this.loadingSuggestions = false;
      return [];
    }
    this.loadingSuggestions = true;
    const requestId = ++this.suggestionsRequestId;
    const { language } = this.$route.params;
    const { query } = this;
    try {
      const response = await SearchService.getSuggestions(language, query, this.searchOptions);
      const scopeIsStillGlobal = !SearchScopeService.hasActiveScope(this.searchOptions);
      const suggestionIsCurrent =
        this.query === query && requestId === this.suggestionsRequestId && scopeIsStillGlobal;
      return suggestionIsCurrent && response ? response.data : undefined;
    } catch (e) {
      return [];
    } finally {
      if (requestId === this.suggestionsRequestId) {
        this.loadingSuggestions = false;
      }
    }
  }

  resetSuggestions() {
    this.suggestions = [];
  }
}
