










































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import { getTranslation } from '@/services/Translation';
import AuthLayout from '@/layouts/AuthLayout.vue';
import Checkbox from '@/components/ui/Checkbox.vue';
import InputText from '@/components/ui/InputText.vue';

@Component({
  components: { InputText, AuthLayout, Checkbox }
})
export default class LoginForm extends Vue {
  loading: boolean = false;
  email: string = '';
  password: string = '';
  error: string = '';
  errors: { [field: string]: Array<string> } = {};
  payload: { [fieldName: string]: string } = {
    email: '',
    password: ''
  };
  rememberMe: boolean = true;

  @Prop({ default: true })
  showForgotPasswordLink?: boolean;

  getTranslation = getTranslation;

  async submit() {
    if (this.loading) {
      return;
    }
    this.error = '';
    this.errors = {};
    this.loading = true;
    try {
      await this.$store.dispatch('auth/login', this.payload);
      this.$emit('authorized');
    } catch (e) {
      if (e.response && e.response.data) {
        this.error = e.response.data.message || getTranslation('defaultErrorMessage');
        this.errors = e.response.data.errors;
      } else {
        this.error = e.message || getTranslation('defaultErrorMessage');
      }
    } finally {
      this.loading = false;
    }
  }

  async onChangeField(fieldName: string, value: string) {
    this.payload[fieldName] = value;
  }
}
