






















































































import Vue from 'vue';
import Component from 'vue-class-component';
import Overlay from '@/components/ui/Overlay.vue';
import { Mutation, State } from 'vuex-class';
import SettingsExample from '@/components/settings/SettingsExample.vue';
import MinusIcon from '@/assets/icons/minus.svg';
import PlusIcon from '@/assets/icons/plus.svg';
import {
  LANGUAGE_CODE_RUSSIAN,
  LANGUAGE_CODE_ENGLISH,
  LIST_SCALE_TABLET,
  LIST_SCALE_DESKTOP,
  LIST_SCALE_AUTO
} from '@/constants';
import { getTranslation } from '@/services/Translation';

@Component({
  components: { SettingsExample, Overlay, MinusIcon, PlusIcon }
})
export default class Settings extends Vue {
  LANGUAGE_CODE_RUSSIAN = LANGUAGE_CODE_RUSSIAN;
  LANGUAGE_CODE_ENGLISH = LANGUAGE_CODE_ENGLISH;
  LIST_SCALE_TABLET = LIST_SCALE_TABLET;
  LIST_SCALE_DESKTOP = LIST_SCALE_DESKTOP;
  LIST_SCALE_AUTO = LIST_SCALE_AUTO;

  getTranslation = getTranslation;

  @State('scale', { namespace: 'reader' })
  scale!: number;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  @State('catalogListScale', { namespace: 'reader' })
  catalogListScale!: string;

  @Mutation('setScale', { namespace: 'reader' })
  setScale!: Function;

  @Mutation('setInterfaceLanguage', { namespace: 'reader' })
  setInterfaceLanguage!: Function;

  @Mutation('setCatalogListScale', { namespace: 'reader' })
  setCatalogListScale!: Function;
}
