

































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import NavItemLink from '@/components/nav/NavItemLink.vue';
import NavItemFolder from '@/components/nav/NavItemFolder.vue';
import { AuthorLetter, Book, BookLetter, NavigationData } from '@/services/Navigation/types';
import NavBook from '@/components/nav/NavBook.vue';
import { Action, Getter, Mutation } from 'vuex-class';
import NavAuthor from '@/components/nav/NavAuthor.vue';

@Component({
  components: { NavBook, NavAuthor, NavItemLink, NavItemFolder }
})
export default class NavLetter extends Vue {
  @Prop({ required: true })
  letter!: BookLetter | AuthorLetter;

  @Prop({ required: true })
  listType!: 'books' | 'authors';

  @Prop({ required: true })
  showCheckboxes!: boolean;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  navData!: NavigationData;

  @Action('fetchLetterBooks', { namespace: 'navigation' })
  fetchLetterBooks!: Function;

  @Mutation('actualizeHighlight', { namespace: 'navigation' })
  actualizeHighlight!: Function;

  @Mutation('toggleBookLetterExpand', { namespace: 'navigation' })
  toggleBookLetterExpand!: Function;

  @Mutation('toggleAuthorLetterExpand', { namespace: 'navigation' })
  toggleAuthorLetterExpand!: Function;

  loading: boolean = false;

  async mounted() {
    await this.loadBooksIfNeeded();
  }

  @Watch('letter.expanded')
  async onLetterExpand(to: boolean, from: boolean) {
    if (to !== from) {
      await this.loadBooksIfNeeded();
    }
  }

  async loadBooksIfNeeded() {
    if (!this.needBooksLoad) {
      return;
    }
    await this.loadBooks();
    this.actualizeHighlight();
  }

  get books() {
    const { books } = this.navData;
    return Object.values(books).filter(book => (this.letter as BookLetter).bookIds.includes(book.id));
  }

  get authors() {
    const { authors } = this.navData;
    return authors.filter(author => (this.letter as AuthorLetter).authorIds.includes(author.id));
  }

  get needBooksLoad() {
    return this.letter.expanded && this.listType === 'books' && !(this.letter as BookLetter).bookIds.length;
  }

  toggleExpand() {
    if (this.listType === 'books') {
      this.toggleBookLetterExpand(this.letter.id);
    } else {
      this.toggleAuthorLetterExpand(this.letter.id);
    }
  }

  async loadBooks() {
    this.loading = true;
    try {
      await this.fetchLetterBooks({
        language: this.$store.state.navigation.language,
        letterName: this.letter.name
      });
    } finally {
      this.loading = false;
    }
  }
}
