





































































































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import { Bookmark } from '@/store/modules/bookmarks';
import { Tab } from '@/store/modules/tabs';
import IconBookmark from '@/assets/icons/bookmark.svg';
import IconCross from '@/assets/icons/cross.svg';
import IconMore from '@/assets/icons/more.svg';
import IconNote from '@/assets/icons/note.svg';
import IconReturn from '@/assets/icons/return.svg';
import { getTranslation } from '@/services/Translation';

@Component({ components: { IconBookmark, IconCross, IconMore, IconNote, IconReturn } })
export default class MobileBookmarkSheet extends Vue {
  @Prop({ required: true })
  visible!: boolean;

  @Prop({ default: null })
  currentTab!: Tab | null;

  @Prop({ required: true })
  bookmarks!: Array<Bookmark>;

  dragOffset = 0;
  dragStartY = 0;
  dragging = false;
  draftNote = '';
  editingBookmarkId: string | number | null = null;
  editingNote = '';
  openActionsBookmarkId: string | number | null = null;
  getTranslation = getTranslation;

  get manualBookmarks() {
    if (!this.currentTab || !this.currentTab.bookKey) {
      return [];
    }
    return this.bookmarks.filter(
      bookmark => bookmark.type === 'manual' && bookmark.bookKey === this.currentTab!.bookKey
    );
  }

  @Watch('visible')
  resetDrag() {
    this.dragOffset = 0;
    this.dragging = false;
    this.draftNote = '';
    this.editingBookmarkId = null;
    this.editingNote = '';
    this.openActionsBookmarkId = null;
  }

  startDrag(event: PointerEvent) {
    this.dragging = true;
    this.dragStartY = event.clientY;
    (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);
  }

  moveDrag(event: PointerEvent) {
    if (!this.dragging) {
      return;
    }
    this.dragOffset = Math.max(0, event.clientY - this.dragStartY);
  }

  finishDrag(event: PointerEvent) {
    if (!this.dragging) {
      return;
    }
    this.dragging = false;
    if ((event.currentTarget as HTMLElement).hasPointerCapture(event.pointerId)) {
      (event.currentTarget as HTMLElement).releasePointerCapture(event.pointerId);
    }
    if (this.dragOffset > 72) {
      this.$emit('close');
    }
    this.dragOffset = 0;
  }

  progressLabel(bookmark: Bookmark) {
    return `${Math.round(bookmark.position * 100)}%`;
  }

  addBookmark() {
    this.$emit('add', this.draftNote.trim());
    this.draftNote = '';
  }

  toggleActions(bookmark: Bookmark) {
    this.openActionsBookmarkId = this.openActionsBookmarkId === bookmark.id ? null : bookmark.id;
  }

  startEditing(bookmark: Bookmark) {
    this.editingBookmarkId = bookmark.id;
    this.editingNote = bookmark.note || '';
    this.openActionsBookmarkId = null;
    this.$nextTick(() => {
      const textarea = this.$el.querySelector('.bookmark-in-book.editing .bookmark-note-edit');
      if (textarea instanceof HTMLTextAreaElement) {
        this.resizeTextarea(textarea);
        textarea.focus();
      }
    });
  }

  saveNote(bookmark: Bookmark) {
    this.$emit('note', { bookmark, note: this.editingNote.trim() });
    this.cancelEditing();
  }

  moveBookmark(bookmark: Bookmark) {
    this.openActionsBookmarkId = null;
    this.$emit('move', bookmark);
  }

  moveEditedBookmark(bookmark: Bookmark) {
    this.$emit('move', { ...bookmark, note: this.editingNote.trim() });
    this.cancelEditing();
  }

  removeBookmark(bookmark: Bookmark) {
    this.openActionsBookmarkId = null;
    this.$emit('remove', bookmark);
  }

  cancelEditing() {
    this.editingBookmarkId = null;
    this.editingNote = '';
  }

  resizeTextarea(eventOrElement: Event | HTMLTextAreaElement) {
    const textarea =
      eventOrElement instanceof HTMLTextAreaElement
        ? eventOrElement
        : (eventOrElement.currentTarget as HTMLTextAreaElement);
    textarea.style.height = 'auto';
    textarea.style.height = `${textarea.scrollHeight}px`;
    textarea.style.overflowY = 'hidden';
  }
}
