import Vue from 'vue';
import router from '@/router';
import {
  Author,
  AuthorLetter,
  Book,
  BookLetter,
  Books,
  BookSection,
  BookSectionEntries,
  Category,
  NavigationData,
  NavigationDataRaw
} from '@/services/Navigation/types';
import Helpers from '@/services/Navigation/Helpers';

export default class ProcessService {
  public static processNavigation(navigation: NavigationDataRaw): Partial<NavigationData> {
    const categories = ProcessService.processCategories(navigation.categories);
    const authors = ProcessService.processAuthors(navigation.authors);
    const authorsAlphabet = ProcessService.makeAuthorsAlphabet(authors);
    const booksAlphabet = ProcessService.processBooksAlphabet(navigation.books_first_letter);
    return {
      booksAlphabet,
      categories,
      authors,
      authorsAlphabet
    };
  }

  public static collapseAll({
    books,
    booksAlphabet,
    categories,
    authors,
    authorsAlphabet,
    foundBooks
  }: NavigationData) {
    return {
      books: Helpers.collapseBooks(books),
      booksAlphabet: Helpers.collapseAll(booksAlphabet),
      categories: Helpers.collapseAll(categories),
      authors: Helpers.collapseAll(authors),
      authorsAlphabet: Helpers.collapseAll(authorsAlphabet),
      foundBooks: Helpers.collapseBooks(foundBooks)
    };
  }

  public static updatePreloadFlag(books: Books) {
    const routeBook = router.currentRoute.params.book;
    const routeBookSection = router.currentRoute.params.bookSection;
    const book = books[routeBook];
    if (!book) {
      return;
    }
    const bookSections = book.children;
    const index = bookSections.findIndex(one => one.book.slug === routeBook && one.slug === routeBookSection);
    const preloadBookSectionAmount = parseInt(process.env.VUE_APP_PRELOAD_BOOK_SECTIONS_AMOUNT, 10);
    let loadBookSectionsBefore = 0;
    // going up along the tree
    for (let i = index; i >= 0; i--) {
      const bookSection = bookSections[i];
      if (i === index) {
        continue;
      }
      if (bookSection.book.slug === routeBook) {
        bookSection.preload = true;
        if (!(bookSection.is_parent && bookSection.preload)) {
          loadBookSectionsBefore++;
        }
      }
      if (loadBookSectionsBefore === preloadBookSectionAmount) {
        break;
      }
    }
    let loadBookSectionsAfter = 0;
    // going down along the tree
    for (let i = index; i < bookSections.length; i++) {
      const bookSection = bookSections[i];
      if (i === index) {
        continue;
      }
      if (bookSection.book.slug === routeBook) {
        bookSection.preload = true;
        if (!(bookSection.is_parent && bookSection.preload)) {
          loadBookSectionsAfter++;
        }
      }
      if (loadBookSectionsAfter === preloadBookSectionAmount) {
        break;
      }
    }
  }

  public static processBooks(books: Array<Book>, props = {}): Books {
    const processedBooks: Books = {};
    books.forEach(book => {
      processedBooks[book.slug] = {
        ...book,
        highlight: false,
        visible: true,
        expanded: false,
        checked: false,
        partiallyChecked: false,
        children: [],
        is_show_edit_link: false,
        edit_link: '',
        ...props
      };
    });
    return processedBooks;
  }

  public static processBookSections(
    bookSections: Array<BookSection>,
    book: Book,
    props = {},
    bookSectionEntries: Array<BookSectionEntries> = []
  ) {
    let prevBookId: null | number = null;
    let number = 0;
    const processedBookSections: Array<BookSection> = [];
    bookSections.forEach(bookSection => {
      prevBookId = bookSection.bookId;
      number++;
      const entries = bookSectionEntries.find(({ code }) => code === bookSection.code);
      processedBookSections.push({
        ...bookSection,
        book,
        id: bookSection.code,
        parentId: bookSection.parent_code,
        highlight: false,
        visible: true,
        expanded: false,
        checked: book.checked,
        partiallyChecked: false,
        number: number - 1,
        doc_count: entries ? entries.quantity : undefined,
        ...props
      });
    });
    return processedBookSections;
  }

  public static processCategories(categories: Array<Category>) {
    return Object.values(categories).map(category => ({
      ...category,
      highlight: false,
      visible: true,
      expanded: false,
      checked: false,
      partiallyChecked: false,
      bookIds: []
    }));
  }

  public static processAuthors(authors: Array<Author>) {
    return authors.map(author => ({
      ...author,
      highlight: false,
      visible: true,
      expanded: false,
      checked: false,
      partiallyChecked: false,
      bookIds: []
    }));
  }

  public static processBooksAlphabet(letters: Array<string>) {
    return letters.map((letter, index) => ({
      id: index,
      name: letter,
      highlight: false,
      visible: true,
      expanded: false,
      bookIds: []
    }));
  }

  public static concatBooks(currentBooks: Books, newBooks: Books) {
    const books: Books = { ...currentBooks };
    Object.values(newBooks).forEach(book => {
      if (!books[book.slug]) {
        Vue.set(books, book.slug, book);
      }
    });
    return books;
  }

  public static mapBookIds<T extends Category | Author | BookLetter>(
    entities: Array<T>,
    entityId: number,
    books: Books
  ): Array<T> {
    const index = entities.findIndex(one => one.id === entityId);
    if (entities[index]) {
      entities[index].bookIds = Object.values(books).map(book => book.id);
    }
    return entities;
  }

  public static makeAuthorsAlphabet(authors: Array<Author>) {
    const mappedAuthors: { [key: string]: Array<any> } = {};
    authors.forEach(author => {
      const letter = author.name[0];
      mappedAuthors[letter] = mappedAuthors[letter] || [];
      mappedAuthors[letter].push(author);
    });

    const alphabet: Array<AuthorLetter> = [];
    Object.keys(mappedAuthors)
      .sort()
      .forEach((letter, index) => {
        alphabet.push({
          id: index,
          name: letter,
          highlight: false,
          visible: true,
          expanded: false,
          authorIds: mappedAuthors[letter].map(one => one.id)
        });
      });

    return alphabet;
  }
}
