





































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import NavItemLink from '@/components/nav/NavItemLink.vue';
import NavItemFolder from '@/components/nav/NavItemFolder.vue';
import { Author, Book, Category, NavigationData } from '@/services/Navigation/types';
import NavBookSection from '@/components/nav/NavBookSection.vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import UrlBuilderService from '@/services/UrlBuilderService';
import { LABEL_OFFSET_PX, LEVEL_OFFSET_PX } from '@/services/Navigation/constants';
import { SearchBaseOptions } from '@/services/Api/SearchService';

@Component({
  components: { NavBookSection, NavItemLink, NavItemFolder }
})
export default class NavBook extends Vue {
  @Prop({ required: true })
  book!: Book;

  @Prop({ required: false })
  category!: Category;

  @Prop({ required: false })
  author!: Author;

  @Prop({ required: false, default: 0 })
  level!: number;

  @Prop({ required: false })
  showCheckboxes!: boolean;

  @Prop({ required: false })
  showEntriesCount?: boolean;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  navData!: NavigationData;

  @Getter('searchOptions', { namespace: 'search' })
  searchOptions!: SearchBaseOptions;

  @Getter('showSearchResults', { namespace: 'navigation' })
  showSearchResults?: boolean;

  @State('language', { namespace: 'navigation' })
  navLanguage!: string;

  @Action('fetchBookSections', { namespace: 'navigation' })
  fetchBookSections!: Function;

  @Action('searchBookSections', { namespace: 'navigation' })
  searchBookSections!: Function;

  @Mutation('toggleBookExpand', { namespace: 'navigation' })
  toggleBookExpand!: Function;

  @Mutation('toggleFoundBookExpand', { namespace: 'navigation' })
  toggleFoundBookExpand!: Function;

  @Mutation('toggleBookCheck', { namespace: 'navigation' })
  toggleBookCheck!: Function;

  @Mutation('toggleFoundBookCheck', { namespace: 'navigation' })
  toggleFoundBookCheck!: Function;

  loading: boolean = false;

  async mounted() {
    if (this.needBookSectionsLoad) {
      await this.loadBookSections();
    }
  }

  @Watch('book.expanded')
  async onBookExpand(to: boolean, from: boolean) {
    if (to !== from && this.needBookSectionsLoad) {
      // if category is expanded and has books and there is no loaded books yet
      await this.loadBookSections();
    }
  }

  get offset() {
    if (!this.level) {
      return LABEL_OFFSET_PX;
    }
    return this.level * LEVEL_OFFSET_PX + LABEL_OFFSET_PX;
  }

  get url() {
    return UrlBuilderService.getBookUrl({
      language: this.book.language,
      categorySlug: this.category ? this.category.slug : '',
      authorSlug: this.author ? this.author.slug : '',
      bookSlug: this.book.slug
    });
  }

  get highlight() {
    const { category, author } = this.$route.params;
    if (this.category && category && this.category.slug !== category) {
      // in case one book linked to several categories
      return false;
    }
    if (this.author && author && this.author.slug !== author) {
      // in case one book has several authors
      return false;
    }
    return this.book.highlight;
  }

  get bookSections() {
    return this.book.children;
  }

  get needBookSectionsLoad() {
    return this.book.expanded && !this.bookSections.length;
  }

  get bookName() {
    return (this.book.status ? `[${this.book.status}] ` : '') + this.book.name;
  }

  toggleExpand() {
    if (this.showSearchResults) {
      this.toggleFoundBookExpand(this.book.slug);
    } else {
      this.toggleBookExpand(this.book.slug);
    }
  }

  toggleCheck() {
    if (this.showSearchResults) {
      this.toggleFoundBookCheck(this.book.slug);
    } else {
      this.toggleBookCheck(this.book.slug);
    }
  }

  async loadBookSections() {
    this.loading = true;
    try {
      if (this.showSearchResults) {
        // if it's a search query
        await this.searchBookSections({
          language: this.$store.state.navigation.language,
          query: this.$route.query.query,
          bookSlug: this.book.slug,
          ...this.searchOptions
        });
      } else {
        // if we expand a book in the catalog (without search)
        await this.fetchBookSections({
          language: this.$store.state.navigation.language,
          bookSlug: this.book.slug
        });
      }
    } finally {
      this.loading = false;
    }
  }
}
