import { store } from '@/store';
import { LANGUAGE_CODE_DEFAULT } from '@/constants';
import { translations } from '@/translations';
import { TranslationStrings } from '@/translations/types';

export const getTranslation = (key: keyof TranslationStrings) => {
  const interfaceLanguage = store.state.reader.interfaceLanguage || LANGUAGE_CODE_DEFAULT;

  return translations[interfaceLanguage][key] || '';
};
