import Vue from 'vue';
import Vuex from 'vuex';
import { module as auth, AuthState } from './modules/auth';
import { module as navigation, NavigationState } from './modules/navigation';
import { module as tabs, TabsState } from './modules/tabs';
import { module as user, UserState } from './modules/user';
import { module as reader, ReaderState } from './modules/reader';
import { module as search, SearchState } from '@/store/modules/search';
import { module as settings, SettingsState } from '@/store/modules/settings';
import { module as bookmarks, BookmarksState } from '@/store/modules/bookmarks';

export interface RootState {
  loading: boolean;
  auth: AuthState;
  navigation: NavigationState;
  tabs: TabsState;
  user: UserState;
  reader: ReaderState;
  search: SearchState;
  settings: SettingsState;
  bookmarks: BookmarksState;
  route: any;
}

Vue.use(Vuex);

export const store = new Vuex.Store({
  state: <RootState>{
    loading: false
  },
  mutations: {
    startLoading(state) {
      state.loading = true;
    },
    stopLoading(state) {
      state.loading = false;
    }
  },
  modules: {
    auth,
    navigation,
    tabs,
    user,
    reader,
    search,
    settings,
    bookmarks
  }
});
