


























import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import NavItemFolder from '@/components/nav/NavItemFolder.vue';
import { Author, Book, NavigationData } from '@/services/Navigation/types';
import NavBook from '@/components/nav/NavBook.vue';
import { Action, Getter, Mutation, State } from 'vuex-class';
import { NavigationState } from '@/store/modules/navigation';
import { LABEL_OFFSET_PX, LEVEL_OFFSET_PX } from '@/services/Navigation/constants';
import UrlBuilderService from '@/services/UrlBuilderService';

@Component({
  components: { NavBook, NavItemFolder }
})
export default class NavAuthor extends Vue {
  @Prop({ required: true })
  author!: Author;

  @Prop({ required: false, default: 0 })
  level!: number;

  @Prop({ required: true })
  showCheckboxes!: boolean;

  @Getter('dataFromStateLanguage', { namespace: 'navigation' })
  navData!: NavigationData;

  @Action('fetchAuthorBooks', { namespace: 'navigation' })
  fetchAuthorBooks!: Function;

  @Mutation('toggleAuthorExpand', { namespace: 'navigation' })
  toggleAuthorExpand!: Function;

  loading: boolean = false;

  async mounted() {
    if (this.needBooksLoad) {
      await this.loadBooks();
    }
  }

  @Watch('author.expanded')
  async onAuthorExpand(to: boolean, from: boolean) {
    if (to !== from && this.needBooksLoad) {
      // if author is expanded and has books and there is no loaded books yet
      await this.loadBooks();
    }
  }

  get offset() {
    if (!this.level) {
      return LABEL_OFFSET_PX;
    }
    return this.level * LEVEL_OFFSET_PX + LABEL_OFFSET_PX;
  }

  get books() {
    const { books } = this.navData;
    return this.author.bookIds.map(bookId => Object.values(books).find(book => book.id === bookId));
  }

  get url() {
    return UrlBuilderService.getAuthorUrl({
      language: this.$store.state.navigation.language,
      authorSlug: this.author.slug
    });
  }

  get needBooksLoad() {
    return this.author.expanded && !this.books.length;
  }

  toggleExpand() {
    this.toggleAuthorExpand(this.author.id);
  }

  async loadBooks() {
    this.loading = true;
    await this.fetchAuthorBooks({
      language: this.$store.state.navigation.language,
      authorId: this.author.id
    });
    this.loading = false;
  }
}
